from __future__ import annotations

# Beginner-facing clarifications appended to generated rule pages.
# Keep these short and practical: they fill the common gaps a new player needs at the table.

BEGINNER_ADDENDA: dict[str, str] = {
    # Dice games
    'farkle': '''<h2>First-time player clarifications</h2><ul><li><strong>Use each die once when scoring.</strong> If three 1s score as a set, those same dice do not also score as single 1s.</li><li><strong>Hot dice:</strong> if all 6 dice score, you may pick them all up and keep rolling, but the whole turn is still at risk until you bank.</li><li><strong>Beginner game length:</strong> play to 10,000 points. When someone reaches it, every other player gets one final turn.</li><li><strong>Opening rule:</strong> for a casual first game, skip the minimum-opening-score rule. Add a 500-point opening requirement later if you want a longer game.</li></ul>''',
    'liars-dice': '''<h2>First-time player clarifications</h2><ul><li>Everyone rolls secretly under a cup. Only you may look at your own dice.</li><li>A bid means “I think at least this many dice of this face exist across the whole table.”</li><li>Each new bid must raise either the quantity or the face value according to your chosen house rule. Keep the rule simple for the whole game.</li><li>If a challenge is wrong, the challenger loses a die. If the bid was too high, the bidder loses a die. Last player with dice wins.</li></ul>''',
    'ship-captain-and-crew': '''<h2>First-time player clarifications</h2><ul><li>You must keep a 6 first, then a 5, then a 4. They are the ship, captain, and crew.</li><li>Only after you have 6-5-4 do the remaining two dice count as cargo.</li><li>Each player gets up to three rolls total. Highest cargo wins the round; tied cargo rerolls or splits the round by house choice.</li><li>Play 5 rounds or first to 3 round wins for a quick game.</li></ul>''',
    'pig': '''<h2>First-time player clarifications</h2><ul><li>Default beginner rule: use 1 die. Roll as many times as you want, adding the roll to your turn total.</li><li>If you roll a 1, your turn ends and you score 0 for that turn only.</li><li>If you stop before rolling a 1, bank your turn total into your game score.</li><li>First to 100 wins. For two-dice Pig, use the same idea: rolling any 1 ends your turn and loses only the current turn total.</li></ul>''',
    'going-to-boston': '''<h2>First-time player clarifications</h2><ul><li>Each turn has three rolls. Roll 3 dice, keep the highest; roll the other 2, keep the highest; roll the last die.</li><li>Add the three kept dice for your turn score.</li><li>Everyone gets the same number of turns. Play 5 rounds; highest total wins.</li><li>If players tie after the final round, tied players each take one sudden-death turn.</li></ul>''',
    'yahtzee-yacht': '''<h2>First-time player clarifications</h2><ul><li>Each player takes 13 turns. On your turn, roll up to three times, keeping any dice between rolls.</li><li>After the final roll, choose one empty score category. You must fill one category every turn, even if it scores 0.</li><li><strong>Upper section:</strong> Ones through Sixes score the total of that face only. Example: three 4s score 12 in Fours.</li><li><strong>Common lower scores:</strong> three/four of a kind = total of all dice; full house = 25; small straight = 30; large straight = 40; chance = total of all dice; Yahtzee/Yacht = five of a kind, usually 50.</li><li>Highest total after all categories are filled wins. Use the printable score sheet so players do not have to remember the categories.</li></ul>''',
    'mia': '''<h2>First-time player clarifications</h2><ul><li>Read the two dice as a two-digit number with the higher die first. A 6 and 3 is 63, not 9.</li><li>The usual high roll is 21, called Mia. Then doubles rank high, then normal numbers from 65 down to 31.</li><li>On your turn, you may tell the truth or bluff about your roll, then pass the covered dice to the next player.</li><li>The next player either accepts and must announce a higher result, or challenges. The loser of the challenge loses a life.</li></ul>''',
    'beetle': '''<h2>First-time player clarifications</h2><ul><li>Each player needs paper and starts with a blank beetle drawing.</li><li>You usually must roll the body before adding other parts, because every other part attaches to it.</li><li>If you roll a part you cannot draw yet or already completed, nothing happens and the turn passes.</li><li>First player to complete their beetle wins.</li></ul>''',
    'tenzi': '''<h2>First-time player clarifications</h2><ul><li>Everyone starts with 10 dice.</li><li>Roll all dice at once, choose one number to chase, and keep dice showing that number.</li><li>Keep rerolling only the dice that do not match your chosen number.</li><li>First player with all 10 dice showing the same number calls “Tenzi” and wins the round.</li></ul>''',
    'bunco': '''<h2>First-time player clarifications</h2><ul><li>Play 6 rounds. In round 1, ones are the target; round 2, twos are the target, and so on through sixes.</li><li>On your turn, roll 3 dice. Score 1 point for each die matching the round number.</li><li>Three dice matching the round number is a Bunco and scores 21 points.</li><li>Three of any other number scores 5 points. If you score anything, keep rolling. If you score 0, your turn ends.</li><li>Beginner ending: each round ends when one player or team reaches 21. After 6 rounds, most round wins or highest total score wins.</li></ul>''',
    'craps': '''<h2>First-time player clarifications</h2><ul><li>For a simple home version, use only the Pass Line bet and tokens with no real money.</li><li>Come-out roll: 7 or 11 wins immediately; 2, 3, or 12 loses immediately.</li><li>Any other number becomes the point. Keep rolling until the point repeats, which wins, or a 7 appears, which loses.</li><li>After the bet resolves, the next roll starts a new come-out roll.</li></ul>''',
    'knucklebones': '''<h2>First-time player clarifications</h2><ul><li>Each player has their own 3-column by 3-row grid. On your turn, roll 1 die and place it in one column on your grid.</li><li>If you place a die in a column, any matching dice in the opponent’s same column are removed.</li><li>Score each column separately. Single dice score face value; matching dice are stronger: two 5s score 20, three 5s score 45.</li><li>When one grid is full, let the other player finish the current round so both players had the same number of turns, then highest total wins.</li></ul>''',
    'cant-stop': '''<h2>First-time player clarifications</h2><ul><li>Roll 4 dice and split them into two pairs. Each pair total moves a marker on that numbered column from 2 to 12.</li><li>You may have only 3 active columns during one turn. Once you start a fourth different number, that pairing is not allowed.</li><li>If at least one legal pair can move, you may keep rolling or stop. If you stop, your temporary progress becomes permanent.</li><li>If no legal pair can move, you bust and lose all temporary progress from that turn.</li><li>When you reach the top of a column and stop safely, you claim that column. First player to claim 3 columns wins.</li></ul>''',
    'shut-the-box': '''<h2>First-time player clarifications</h2><ul><li>Start with numbers 1–9 open. Roll 2 dice and close any open numbers that add to the roll.</li><li>Example: roll 8, close 8, or 5+3, or 4+3+1 if those numbers are open.</li><li>Keep rolling until no open combination matches your roll. Your score is the sum of numbers left open; low score is better.</li><li>For solo play, try to shut every number. For multiplayer, everyone gets one turn and lowest score wins.</li></ul>''',
    'qwixx-style-roll-and-write': '''<h2>First-time player clarifications</h2><ul><li>Use 2 neutral dice and 4 “row dice.” If your dice are all the same color, assign four dice to rows before the game starts and mark them on the sheet.</li><li>Each turn, the active player rolls all 6 dice. Everyone may mark the neutral-dice total in any row where that number is still legal.</li><li>The active player may also mark one row using one neutral die plus that row’s assigned die.</li><li>Numbers must be marked left to right. Once you skip a number in a row, you can never mark that number later.</li><li>To lock a row, you usually need at least 5 marks in that row and then mark the far-right lock number. A locked row cannot be used again.</li><li>If the active player marks nothing, they take one penalty. End the game after 4 penalties by one player or after 2 rows are locked. Score rows by number of marks; most points wins.</li></ul>''',
    'martinetti-mountain-matterhorn': '''<h2>First-time player clarifications</h2><ul><li>The goal is to move up the track by making 1, then 2, then 3, and so on.</li><li>On a roll, each die may be used only once. You may use single dice or add dice together to make the next needed number.</li><li>You may advance multiple spaces in one roll if the dice can make the next numbers in order.</li><li>If you cannot make the next number, your turn ends. First player to reach the top and usually return back down wins.</li></ul>''',
    'chicago': '''<h2>First-time player clarifications</h2><ul><li>Play 11 rounds with target totals from 2 through 12.</li><li>In each round, every player rolls 2 dice once. If your total matches the round target, score that target number; otherwise score 0.</li><li>After round 12, highest total score wins. Ties can be broken with one extra roll each.</li></ul>''',
    'threes-thirty': '''<h2>First-time player clarifications</h2><ul><li>This is a low-score game. Threes usually count as 0; all other dice count face value.</li><li>On your turn, roll, keep at least one die, and reroll the rest until all dice are kept or you choose to stop.</li><li>Play 5 rounds. Add each player’s round scores; lowest total wins.</li></ul>''',
    'drop-dead': '''<h2>First-time player clarifications</h2><ul><li>Roll 5 dice. Any 2s or 5s are “dead” and removed.</li><li>If you rolled no 2s or 5s, score the total of all dice and roll them again.</li><li>Keep going until all dice are dead. Then the next player takes a turn.</li><li>Play one turn each for a quick game, or 5 rounds for a fuller game. Highest score wins.</li></ul>''',
    'poker-dice': '''<h2>First-time player clarifications</h2><ul><li>Each player gets up to three rolls, keeping or rerolling any dice between rolls.</li><li>Best hand wins the round. Ranking: five of a kind, four of a kind, full house, straight, three of a kind, two pair, one pair, high die.</li><li>Straights are 1-2-3-4-5 and 2-3-4-5-6. For ties, compare the rank value first, then highest remaining dice.</li><li>Play 5 rounds; most round wins wins the game.</li></ul>''',
    'sevens-out': '''<h2>First-time player clarifications</h2><ul><li>Roll 2 dice and add each roll to your turn total.</li><li>If you roll a 7, your turn ends and you score 0 for that turn.</li><li>You may stop before rolling a 7 and bank your turn total.</li><li>First to 100 wins, or play 5 rounds and highest total wins.</li></ul>''',
    'beat-that': '''<h2>First-time player clarifications</h2><ul><li>Everyone uses the same number of dice.</li><li>After rolling, arrange your dice to make the biggest possible number. Example: 6, 4, and 2 becomes 642.</li><li>Highest number wins the round. Play 5 rounds; most round wins wins the game.</li></ul>''',
    'skunk': '''<h2>First-time player clarifications</h2><ul><li>Everyone stands in for a round if they want to keep risking points. Players may sit down before a roll to bank points for that round.</li><li>If a 1 appears, standing players lose the unbanked points for that round. If double 1s appear, use your chosen house penalty before starting.</li><li>Play one round for each letter in SKUNK. Highest total after all 5 rounds wins.</li></ul>''',
    'midnight': '''<h2>First-time player clarifications</h2><ul><li>Roll 6 dice up to three times. You must keep a 1 and a 4 to qualify.</li><li>After qualifying with 1 and 4, the other four dice are your score.</li><li>If you do not have both 1 and 4 after three rolls, your score is 0.</li><li>Highest score wins the round. Play 5 rounds or use tokens for round wins.</li></ul>''',
    'stuck-in-the-mud': '''<h2>First-time player clarifications</h2><ul><li>Roll 5 dice. Any 2s or 5s become stuck and are set aside.</li><li>If at least one die is stuck, score nothing for that roll and reroll only the dice that are not stuck.</li><li>If no dice are stuck, score the total of the roll and keep rolling all active dice.</li><li>Your turn ends when all dice are stuck. Play 5 rounds; highest total wins.</li></ul>''',
    'three-or-more': '''<h2>First-time player clarifications</h2><ul><li>Roll 5 dice and score only sets of three or more matching dice.</li><li>If you roll exactly one pair, you may reroll the other 3 dice to try to improve to three of a kind.</li><li>Two pair still counts as “a pair” for this beginner version: choose one pair to keep and reroll the other 3 dice.</li><li>No set after the allowed reroll scores 0. First to 20 points wins.</li></ul>''',
    'crag': '''<h2>First-time player clarifications</h2><ul><li>Each turn, roll 3 dice up to three times, keeping any dice between rolls.</li><li>After rolling, choose one empty scorecard category. You must fill one category every turn.</li><li>Use the printable scorecard so players can see categories and avoid arguing over scoring.</li><li>When all categories are filled, highest total wins.</li></ul>''',
    'aces-in-the-pot': '''<h2>First-time player clarifications</h2><ul><li>Give each player the same number of tokens, usually 3.</li><li>On your turn, roll 2 dice. Aces usually send tokens to the pot, sixes pass tokens to a neighbor, and other results do nothing.</li><li>If you have fewer than 2 tokens, roll only as many dice as tokens you have.</li><li>The last player with tokens wins the pot.</li></ul>''',
    'cee-lo-456': '''<h2>First-time player clarifications</h2><ul><li>Roll 3 dice. A clear ranking keeps arguments down.</li><li>Beginner ranking, best to worst: 4-5-6 automatic win; triples, higher triple beats lower; point rolls, where a pair sets the point and the third die is the value; no pair/no special = reroll or bust by house rule; 1-2-3 automatic loss.</li><li>If two players have the same type of result, compare the point or triple value. Exact ties reroll.</li></ul>''',
    'left-center-right': '''<h2>First-time player clarifications</h2><ul><li>Give each player 3 tokens. Roll up to 3 dice: one die for each token you currently have, maximum 3.</li><li>Use a simple mapping before play, such as 1 = left, 2 = center, 3 = right, 4–6 = keep.</li><li>Tokens in the center are out of play. Players with 0 tokens skip rolling but are not eliminated.</li><li>Last player with any tokens wins.</li></ul>''',
    'dice-golf': '''<h2>First-time player clarifications</h2><ul><li>Play 9 or 18 holes. Each hole is one turn per player.</li><li>On a hole, roll up to three times, keeping any dice between rolls to make the best low golf score your rules use.</li><li>Lower score is better. Everyone gets the same number of holes.</li><li>If tied after the last hole, tied players play one sudden-death hole.</li></ul>''',
    'sic-bo': '''<h2>First-time player clarifications</h2><ul><li>Use tokens only. Everyone places optional bets, then one player rolls 3 dice.</li><li>Pay winning bets from the bank and return losing bets to the bank.</li><li>Beginner bets: Big = total 11–17 except triples, Small = total 4–10 except triples, Any Triple = all three dice match, Specific Number = your chosen number appears.</li><li>Keep each bet type written separately on the table aid so new players can check condition and payout quickly.</li></ul>''',
    'help-your-neighbor': '''<h2>First-time player clarifications</h2><ul><li>Assign each player a number from 1 to 6. Unassigned numbers do nothing.</li><li>Give each player the same number of tokens, usually 5.</li><li>On a roll, each die helps the player assigned to that number remove 1 token.</li><li>First player to remove all their tokens wins.</li></ul>''',
    'pair-pressure': '''<h2>First-time player clarifications</h2><ul><li>Roll 6 dice and pair dice to cover target totals on the 2–12 board. Each die can be used only once before rerolling.</li><li>If you use all 6 dice, pick them all back up and keep going with a fresh roll.</li><li>If only 1 unused die remains, you cannot make another pair; bank if you can, or continue only if the rules tell you to reroll after using all dice.</li><li>If no legal pair can cover an open target, you bust and lose the unbanked turn score. First to the target score wins.</li></ul>''',
    'twenty-one-dice-blackjack': '''<h2>First-time player clarifications</h2><ul><li>For a simple game, do not use a dealer. Each player takes one turn trying to get close to 21 without going over.</li><li>Roll 2 dice, add the total, then choose to roll again or stop.</li><li>If you go over 21, you bust and score 0 for the round.</li><li>After everyone has one turn, closest to 21 wins the round. Ties share the win or reroll.</li></ul>''',
    'mexico': '''<h2>First-time player clarifications</h2><ul><li>This version plays like a bluffing escalation game. Read the dice as a two-digit number with the higher die first.</li><li>Ranking: 21 is best, then doubles from 66 down to 11, then normal rolls from 65 down to 31.</li><li>Each player must announce a result higher than the previous claim or challenge it.</li><li>After a challenge, reveal the dice. The losing player loses a life, then starts the next round.</li></ul>''',
    'bar-dice': '''<h2>First-time player clarifications</h2><ul><li>Each player gets up to three rolls to make the best hand.</li><li>Decide before play whether ties use highest dice/kickers or a reroll. For beginners, reroll exact ties.</li><li>Play 5 rounds. Highest hand wins each round; most round wins wins the game.</li></ul>''',
    'solo-farkle-challenge': '''<h2>First-time player clarifications</h2><ul><li>Use normal Farkle scoring and the “use each die once” rule.</li><li>Play exactly 10 turns. Banked points are safe; an unbanked Farkle scores 0 for that turn.</li><li>If all 6 dice score, you may roll all 6 again as hot dice.</li><li>Good targets: 5,000 is solid, 7,500 is strong, and 10,000 is excellent.</li></ul>''',
    'pair-pressure-solo-challenge': '''<h2>First-time player clarifications</h2><ul><li>Use the normal Pair Pressure board and scoring chart.</li><li>Play a fixed number of turns, usually 10, and try to beat your previous score.</li><li>When no legal pair can cover an open number, the turn busts unless you banked before rolling.</li><li>Keep the scoring chart visible; the solo challenge is much easier to learn when the board and values are in front of you.</li></ul>''',
    'dice-solitaire-patience-dice': '''<h2>First-time player clarifications</h2><ul><li>This is a solo puzzle. Set a clear target before starting, such as highest score after 10 turns.</li><li>Write down each turn score immediately so you do not have to remember prior rolls.</li><li>If a choice is ambiguous, use the same choice consistently for the whole game rather than changing mid-game.</li></ul>''',
    'bowling-dice': '''<h2>First-time player clarifications</h2><ul><li>Beginner mode: ignore full bowling bonus math and score only pins knocked down each frame.</li><li>Play 10 frames. Each frame gives up to two rolls to knock down as many pins as possible.</li><li>If using real bowling scoring, a strike scores 10 plus your next two rolls; a spare scores 10 plus your next one roll.</li><li>Use the printable score sheet or simple pins-only scoring for first-time players.</li></ul>''',
    'cho-han': '''<h2>First-time player clarifications</h2><ul><li>Players bet tokens on whether the total of 2 dice will be odd or even.</li><li>Cho means even; Han means odd.</li><li>Roll the dice openly, settle token bets, then start the next round.</li></ul>''',
    'chuck-a-luck': '''<h2>First-time player clarifications</h2><ul><li>Players choose a number from 1 to 6 and place tokens on it.</li><li>Roll 3 dice. A player wins based on how many dice show their chosen number.</li><li>No matching dice means the bet loses. One, two, or three matches pay more according to your house payout chart.</li></ul>''',
    'knock-out-dice': '''<h2>First-time player clarifications</h2><ul><li>Beginner default: each player secretly or openly chooses one knockout number, usually 6, 7, 8, or 9.</li><li>On your turn, roll 2 dice. If the total is your knockout number, your turn ends and you score 0 for that turn.</li><li>Otherwise, add the roll to your turn score and choose whether to roll again or stop and bank.</li><li>First to 100 wins. Use lives/elimination only as an optional variant.</li></ul>''',
    'dice-baseball': '''<h2>First-time player clarifications</h2><ul><li>Play 9 innings. Each half-inning ends after 3 outs.</li><li>Use the result chart to decide whether a roll is an out, walk, single, double, triple, or home run.</li><li>On hits, runners advance the matching number of bases. On a walk, only forced runners advance.</li><li>If tied after 9 innings, play extra innings until one player leads after a complete inning.</li></ul>''',
    'horse-race-dice': '''<h2>First-time player clarifications</h2><ul><li>Each horse is a number, usually 2 through 12. Roll 2 dice; the horse matching the total moves forward.</li><li>Before the race, players may back a horse with tokens or just pick favorites for fun.</li><li>First horse to reach the finish line wins.</li><li>If using tokens, agree on simple payouts before rolling. For family play, skip payouts and race for bragging rights.</li></ul>''',

    # Card games
    'war': '''<h2>First-time player clarifications</h2><ul><li>Aces are high. Suits do not matter.</li><li>If there is a war and a player does not have enough cards for the full face-down/face-up sequence, they put in as many as they can. If they cannot reveal a final battle card, they lose the war.</li><li>For a shorter game, play 10 minutes and count cards; most cards wins.</li></ul>''',
    'crazy-eights': '''<h2>First-time player clarifications</h2><ul><li>Pick a starting player and continue clockwise.</li><li>If you draw a playable card, beginner rule: you may play it immediately.</li><li>If the first discard is an 8, the dealer chooses the starting suit.</li><li>If the draw pile runs out, shuffle the discard pile except the top card to make a new draw pile.</li></ul>''',
    'spoons': '''<h2>First-time player clarifications</h2><ul><li>Put one fewer spoon than the number of players in the middle.</li><li>The dealer draws one card from the deck, keeps one card from their hand, and passes one card left. Each player does the same with the card they receive.</li><li>The last player discards to a waste pile. If the stock runs out, shuffle the waste pile and continue.</li><li>When someone gets four of a kind, they take a spoon. Everyone may then grab one. The player without a spoon gets a letter or is eliminated.</li></ul>''',
    'speed': '''<h2>First-time player clarifications</h2><ul><li>Two players split the deck. Each player gets a 5-card hand and a personal draw pile.</li><li>Set two face-up center cards between players. Put small face-down side piles beside them to restart play when both players are stuck.</li><li>Players play at the same time, placing cards one rank higher or lower than either center card. Suits do not matter.</li><li>Whenever you play a card, draw back up to 5 from your personal pile if possible.</li><li>First player to empty both their hand and draw pile wins.</li></ul>''',
    'spit': '''<h2>First-time player clarifications</h2><ul><li>Each player builds five tableau piles in front of them, then keeps the remaining cards as a face-down spit pile.</li><li>Only exposed tableau cards may be played to the two center spit piles, one rank higher or lower regardless of suit.</li><li>Empty tableau spaces are filled from your own tableau first, then from your spit pile if needed.</li><li>When both players are stuck, each player says “spit” and flips one card from their spit pile to a center pile.</li><li>When a player empties their tableau, both players slap a center pile. Each player takes one pile, shuffles it with their remaining cards, and deals the next round. The goal is to run out of cards.</li></ul>''',
    'shithead-palace-karma': '''<h2>First-time player clarifications</h2><ul><li>After the deal, allow players to swap cards between their hand and face-up table cards before play starts.</li><li>On your turn, play equal or higher than the current top card unless a special card changes the rule.</li><li>Beginner specials: 2 resets the pile, 10 burns/clears the pile, and 7 means the next play must be 7 or lower.</li><li>If you play a face-down table card blindly and it is illegal, pick up the discard pile.</li><li>First player with no hand, no face-up cards, and no face-down cards wins.</li></ul>''',
    'bs-cheat': '''<h2>First-time player clarifications</h2><ul><li>Players must play at least one card on their turn.</li><li>Ranks usually progress A, 2, 3, and so on through K, then wrap back to A.</li><li>After a challenge, the pile is taken by the liar if caught or by the challenger if the play was honest.</li><li>Then play continues with the next rank from the next player, unless your group agrees to restart at A.</li></ul>''',
    'president': '''<h2>First-time player clarifications</h2><ul><li>Decide before play whether equal ranks can be played or whether each play must be strictly higher.</li><li>Beginner rule: 2 is simply the highest rank; it does not automatically clear the pile unless you choose that variant.</li><li>When everyone passes, clear the pile. The player who made the last successful play starts the next pile.</li><li>Record finishing order. First out becomes President next round; last out becomes the lowest rank.</li></ul>''',
    'golf-card-game': '''<h2>First-time player clarifications</h2><ul><li>When one player reveals all their cards, every other player gets one final turn.</li><li>Then all unrevealed cards are flipped and scored.</li><li>Beginner rule: matching cards cancel only in vertical columns, not rows.</li><li>Play 9 hands for a short game or 18 hands for a full “golf” game. Lowest total wins.</li></ul>''',
    'rummy': '''<h2>First-time player clarifications</h2><ul><li>Melds are sets of the same rank or runs in the same suit.</li><li>Beginner rule: aces are low only, so A-2-3 is valid but Q-K-A is not.</li><li>If the draw pile runs out, shuffle the discard pile except its top card to make a new draw pile.</li><li>When someone goes out, other players score penalty points for cards left in hand. Low score after a target, such as 100, wins.</li></ul>''',
    'gin-rummy': '''<h2>First-time player clarifications</h2><ul><li>Deadwood is the value of cards not used in melds. Number cards count face value; face cards count 10; aces count 1.</li><li>You may knock when your deadwood is 10 or less. Lay down melds, then the opponent may lay off matching cards if allowed.</li><li>The knocker scores the difference in deadwood. If the opponent has equal or lower deadwood, the opponent undercuts and scores a bonus.</li><li>Going gin means all cards are in melds except the discard. Gin scores a bonus. Play to 100 points.</li></ul>''',
    'canasta': '''<h2>First-time player clarifications</h2><ul><li>Canasta is heavier than most games in this kit. Treat this page as a table-friendly overview unless everyone already knows the basics.</li><li>A meld is 3 or more cards of the same rank. A canasta is a meld of 7 or more cards.</li><li>Wild cards usually include 2s and jokers. Red and black 3s have special scoring rules.</li><li>Before play, agree on initial meld requirements, discard-pile pickup rules, and whether a canasta must be clean to go out.</li><li>Beginner recommendation: keep the printable/reference open while learning rather than trying to memorize all scoring.</li></ul>''',
    'kemps': '''<h2>First-time player clarifications</h2><ul><li>Partners secretly agree on a signal before the round starts.</li><li>Players swap cards from their hand with face-up center cards, usually all at the same time.</li><li>If your partner has four of a kind and you call “Kemps,” your team scores 1 point.</li><li>If you correctly call “Counter-Kemps” on another team, your team scores 1 point. False calls give the other team 1 point.</li><li>First team to 5 points wins.</li></ul>''',
    'hearts': '''<h2>First-time player clarifications</h2><ul><li>Beginner recommendation: play with exactly 4 players. The page’s wider player count needs variant dealing rules.</li><li>Each heart is 1 point and the queen of spades is 13 points. Low score is good.</li><li>You must follow suit if you can. If you cannot, you may play any card unless using a first-trick restriction.</li><li>Common beginner rule: no points may be played on the first trick.</li><li>Play until someone reaches 100; lowest score wins.</li></ul>''',
    'spades': '''<h2>First-time player clarifications</h2><ul><li>Beginner target score: 500 points.</li><li>Players bid how many tricks they expect to win. Team bids are added together in partnership play.</li><li>You must follow suit if possible. Spades cannot be led until broken unless a player has only spades.</li><li>Nil bids are optional; skip them for the first game if players are new.</li></ul>''',
    'egyptian-rat-screw': '''<h2>First-time player clarifications</h2><ul><li>After someone wins a pile, that player places the next card and play resumes from them.</li><li>First hand touching the pile wins a legal slap. If disputes happen, use the bottom hand as winner.</li><li>Beginner rule: eliminated players are out and cannot slap back in. Add slap-back-in later if desired.</li></ul>''',
    'spider-solitaire': '''<h2>First-time player clarifications</h2><ul><li>For a first game, use one-suit Spider if possible. Two-suit and four-suit are much harder.</li><li>Build tableau cards downward by rank. Full King-to-Ace sequences of the same suit are removed.</li><li>Deal a new row from the stock only when every tableau column has at least one card.</li></ul>''',
    'cribbage': '''<h2>First-time player clarifications</h2><ul><li>Cribbage has two scoring phases: points during play, then points when hands are counted.</li><li>During play, players alternate cards without letting the running total exceed 31. If you cannot play, say “go.”</li><li>Common play points: 15 scores 2, 31 scores 2, pairs/runs score immediately, and last card before reset scores 1.</li><li>After play, count non-dealer hand, dealer hand, then crib. Use a score sheet if you do not have a cribbage board.</li><li>Nobs usually means a jack in your hand matching the starter suit scores 1. His heels usually means a starter jack gives dealer 2.</li></ul>''',
    'casino-cassino': '''<h2>First-time player clarifications</h2><ul><li>Number cards count face value. Aces usually count 1. Agree on face-card capture rules before play.</li><li>You capture by playing a card that matches a table card or matches the total of multiple table cards.</li><li>A build combines table cards into a declared value, such as building 3+4 into 7 because you hold a 7.</li><li>When the deck is gone, the player who made the last capture takes remaining table cards.</li><li>Score after each deal; first to 21 points is a common target.</li></ul>''',
    'durak': '''<h2>First-time player clarifications</h2><ul><li>The attacker plays one card. The defender beats it with a higher card of the same suit or any trump.</li><li>Other attackers may add cards matching ranks already on the table, but do not overload new players; limit attacks to the defender’s hand size.</li><li>If the defender beats all attacks, the cards are discarded. If not, the defender picks them up.</li><li>The goal is to run out of cards. The last player holding cards is the fool.</li></ul>''',
    'oh-hell-oh-pshaw': '''<h2>First-time player clarifications</h2><ul><li>Players bid how many tricks they will take. The goal is exact prediction, not simply taking the most tricks.</li><li>The dealer should make the total bids not equal the number of tricks. Example: if 5 cards are dealt and bids so far total 4, dealer may not bid 1.</li><li>If no card remains to turn for trump, play the hand with no trump.</li><li>Ties in final score can stand, or tied players play one extra hand.</li></ul>''',
    'euchre': '''<h2>First-time player clarifications</h2><ul><li>The maker is the player or team that chooses trump. They are promising to win at least 3 of the 5 tricks.</li><li>If the makers win fewer than 3 tricks, they are euchred and the other team scores.</li><li>The jack of trump is the right bower and highest card. The jack of the same-color suit is the left bower and also counts as trump. Example: if hearts are trump, jack of diamonds is trump too.</li><li>Skip going alone for the first game unless someone already knows Euchre.</li></ul>''',
    'thirty-one-scat-blitz': '''<h2>First-time player clarifications</h2><ul><li>Your hand value is the best total in one suit only. Cards from other suits do not add to that suit total.</li><li>If a player knocks, everyone else gets one final turn, then hands are compared.</li><li>If the knocker ties for lowest or has the lowest hand, use the penalty your group chose for a failed knock.</li><li>Beginner rule: a natural 31 ends the round immediately.</li></ul>''',
    'kings-in-the-corner': '''<h2>First-time player clarifications</h2><ul><li>Build piles downward in alternating colors, like red 9 on black 10.</li><li>Only kings may start an empty corner pile.</li><li>When moving a pile, the bottom card of the moved pile must legally fit on the top card of the destination pile.</li><li>First player to empty their hand wins the round.</li></ul>''',
    'chase-the-ace': '''<h2>First-time player clarifications</h2><ul><li>Each player starts with the same number of lives, usually 3.</li><li>After the round reveal, the lowest card loses one life. Aces are low in many versions; confirm before play.</li><li>Players with 0 lives are out. Continue with the remaining players until one player remains.</li></ul>''',
    'five-card-draw-poker': '''<h2>First-time player clarifications</h2><ul><li>Use tokens, candy, or coins only; no real-money betting needed.</li><li>Betting words: check = bet nothing if allowed; bet = put tokens in; call = match the current bet; raise = increase it; fold = quit the hand.</li><li>Deal 5 cards to each player, run one betting round, let players discard and draw replacements, then run a final betting round.</li><li>Best poker hand among players still in wins the pot. Use a fixed betting limit for beginners.</li></ul>''',
    'texas-holdem': '''<h2>First-time player clarifications</h2><ul><li>Use tokens only. The dealer button marks whose turn order rotates each hand.</li><li>The two players left of the button post small and big blinds before cards are dealt.</li><li>Each player gets 2 private cards. Five community cards are revealed in stages: flop 3, turn 1, river 1.</li><li>Betting happens before the flop, after the flop, after the turn, and after the river. Best 5-card poker hand wins.</li><li>For beginners, use a tiny fixed limit and keep a poker-hand ranking chart open.</li></ul>''',
    'indian-poker-blind-mans-bluff': '''<h2>First-time player clarifications</h2><ul><li>Each player gets one card and holds it to their forehead without looking at it.</li><li>You can see everyone else’s card but not your own.</li><li>Use one simple betting round with a fixed limit: players may stay in by matching the bet or fold.</li><li>After betting, reveal cards. Highest card among players still in wins.</li></ul>''',
    'klondike-solitaire': '''<h2>First-time player clarifications</h2><ul><li>Build tableau columns downward in alternating colors. Build foundations upward by suit from ace to king.</li><li>Beginner rule: draw one card from the stock at a time.</li><li>When the stock runs out, turn the waste pile over to make a new stock. Limit or unlimited recycling is a house choice; unlimited is easiest.</li></ul>''',
    'freecell': '''<h2>First-time player clarifications</h2><ul><li>All cards start face up. Empty free cells are temporary parking spots.</li><li>For a first game, move one card at a time unless the computer/table layout makes a larger move obviously legal.</li><li>Empty columns and free cells increase how many cards can be moved as a sequence.</li></ul>''',
    'pyramid-solitaire': '''<h2>First-time player clarifications</h2><ul><li>Remove pairs that total 13. Kings count as 13 and are removed alone.</li><li>Beginner rule: the top waste card may pair with an uncovered pyramid card or the current stock card if your layout allows it.</li><li>Allow one pass through the stock for a harder game or unlimited passes for a relaxed first game.</li></ul>''',
    'accordion-solitaire': '''<h2>First-time player clarifications</h2><ul><li>Only the top card of each pile matters for matching.</li><li>A pile may move onto the pile immediately to its left, or three piles to its left, if the top cards match by rank or suit.</li><li>The goal is to compress the whole deck into as few piles as possible, ideally one.</li></ul>''',
    'clock-solitaire': '''<h2>First-time player clarifications</h2><ul><li>Cards are arranged like a clock: aces at 1, twos at 2, and so on; kings go in the center.</li><li>Reveal a card and place it under the pile matching its rank, then reveal the next card from that pile.</li><li>The fourth king usually ends the game because it sends you back to the center with no unrevealed center card. Win by revealing all other cards before that happens.</li></ul>''',
    'golf-solitaire': '''<h2>First-time player clarifications</h2><ul><li>Play cards from the tableau onto the waste if they are one rank higher or lower than the waste card.</li><li>Suits do not matter.</li><li>Beginner rule: no stock recycling. When the stock is gone and no moves remain, count remaining tableau cards as your score; lower is better.</li></ul>''',
    'canfield-solitaire': '''<h2>First-time player clarifications</h2><ul><li>The reserve pile is the heart of the game; try to empty it.</li><li>Foundations build upward by suit and may wrap from king to ace if your starting foundation rank requires it.</li><li>Beginner rule: when the stock is exhausted, turn the waste over and continue; allow unlimited redeals while learning.</li></ul>''',
    'bowling-solitaire': '''<h2>First-time player clarifications</h2><ul><li>Lay out 10 “pin” cards in a triangle. The front pin is closest to you; the back row has four cards.</li><li>Use the bowling/deck rules to clear pins. If full bowling scoring is too much, use beginner pins-only scoring: cleared cards = pins knocked down.</li><li>Play 10 frames. Reset the pin layout each frame.</li><li>Aces are usually 1 unless your printed rules say otherwise.</li></ul>''',
    'mao': '''<h2>First-time player clarifications</h2><ul><li>Do not let all players read the hidden-rule section if you want the true Mao experience.</li><li>Use two sections: public rules read aloud, and dealer-only starter rules.</li><li>The rule keeper may play, but should enforce penalties consistently and avoid explaining hidden rules directly.</li><li>When someone wins a round, they may add one new secret rule for the next round.</li></ul>''',
    'nerts-pounce': '''<h2>First-time player clarifications</h2><ul><li>Each player needs their own deck with a distinct back design.</li><li>You may play from your Nerts pile, work piles, and stock/waste to shared center foundations.</li><li>When someone empties their Nerts pile and calls “Nerts,” the round stops immediately.</li><li>Sort center cards by deck backs before scoring so each player gets their own cards back.</li></ul>''',
    'slapjack': '''<h2>First-time player clarifications</h2><ul><li>Players flip cards one at a time into a center pile without looking early.</li><li>When a jack appears, the first hand touching the pile wins it.</li><li>If players slap at nearly the same time, bottom hand wins.</li><li>The player who wins a pile shuffles it into their stack and starts the next flip.</li></ul>''',
    'ninety-nine-card-game': '''<h2>First-time player clarifications</h2><ul><li>Players must play a card on their turn, even if it makes the total go over 99.</li><li>If your play makes the total exceed 99, you lose a life or are out, depending on your chosen version.</li><li>After a player is out, shuffle and redeal 3 cards to each remaining player for the next round.</li></ul>''',
    'in-between-acey-deucey': '''<h2>First-time player clarifications</h2><ul><li>Players ante tokens into a pot, then take turns revealing two outside cards.</li><li>The active player bets whether the next card will fall between them.</li><li>If the outside cards are equal, use a house rule before play: either redeal them or require the third card to be higher/lower by declaration.</li><li>If the pot is empty or too small to pay, everyone antes again before continuing.</li></ul>''',
    'knockout-whist': '''<h2>First-time player clarifications</h2><ul><li>With one 52-card deck, the starting hand size must fit the player count. For 8 or more players, start with fewer than 7 cards.</li><li>Each hand, players try to win at least one trick. Anyone who wins no tricks is knocked out or loses a life, depending on your version.</li><li>If multiple players take no tricks in the same hand, all of them suffer the knockout/life penalty.</li><li>Reduce hand size each round until one player remains or until your agreed final hand is complete.</li></ul>''',
}
